public class SphericalCapAreaCalculator {
public static void main(String[] args) {
Scanner sc = new Scanner(System.in);
//prompt user for input
System.out.print("Enter the radius of the spherical cap: ");
while (!sc.hasNextDouble()) { //check if input is numeric
System.out.println("Invalid input. Please enter a numeric value.");
sc.next();
}
double radius = sc.nextDouble();
System.out.print("Enter the height of the spherical cap: ");
while (!sc.hasNextDouble()) {
System.out.println("Invalid input. Please enter a numeric value.");
sc.next();
}
double height = sc.nextDouble();
//check if input is positive
if (radius <= 0 || height <= 0) {
System.out.println("Invalid input. Please enter a positive value.");
} else {
//calculate area of spherical cap
double baseArea = Math.PI * Math.pow(radius, 2);
double slantHeight = Math.sqrt(Math.pow(radius, 2) + Math.pow(height, 2));
double lateralArea = 2 * Math.PI * radius * slantHeight;
double area = baseArea + lateralArea;
//display result
System.out.printf("The area of the spherical cap is: %.2f", area); //round to 2 decimal places
}
sc.close();
}
}

