double slantHeight = Math.sqrt(Math.pow(radius, 2) + Math.pow(height, 2)); //calculate the slant height of the cap
double lateralArea = 2 * Math.PI * radius * slantHeight; //calculate the lateral area of the cap
double area = baseArea + lateralArea; //add the base area and lateral area to get the total area
