1. Saving Data to Firebase Realtime Database
```
// Initialize Firebase database reference
var database = firebase.database().ref();
// Save data to Firebase
database.child("users").push({
name: "John Doe",
email: "johndoe@email.com"
});
```
2. Retrieving Data from Firebase Realtime Database
```
// Get reference to Firebase data
var database = firebase.database().ref("users");
// Listen for data changes in Firebase
database.on("value", function(snapshot) {
// Parse the snapshot data
snapshot.forEach(function(childSnapshot) {
var data = childSnapshot.val();
console.log(data.name);
});
});
```
3. Authenticating Users with Firebase Authentication
```
// Initialize Firebase authentication reference
var auth = firebase.auth();
// Sign in user with email and password
auth.signInWithEmailAndPassword(email, password).then(function(user) {
// User signed in successfully
}).catch(function(error) {
// Handle sign in errors
});
// Listen for changes in user authentication state
auth.onAuthStateChanged(function(user) {
// User is either signed in or signed out
if (user) {
console.log(user.email + " is signed in");
} else {
console.log("No user is signed in");
}
});
```
