#include <iostream>
#include <stack>
using namespace std;
// Function to check if a given integer is a palindrome
bool isPalindrome(int number) {
// Create a stack to store individual digits
stack<int> digits;
// Push each digit of the given number onto the stack
int copy = number;
while (copy != 0) {
digits.push(copy % 10);
copy /= 10;
}
// Pop each digit from the stack and compare with the corresponding digit in the number
while (!digits.empty()) {
int digit = digits.top();
digits.pop();
if (digit != number % 10) {
return false;
}
number /= 10;
}
return true;
}
