```python
class Node:
def __init__(self, val):
self.val = val
self.left = None
self.right = None
def delete_node(root, key):
if root is None:
return root
# Base case: leaf node
if root.left is None and root.right is None:
if root.val == key:
return None
else:
return root
# Find the node to delete
queue = [root]
key_node = None
while queue:
node = queue.pop(0)
if node.val == key:
key_node = node
if node.left:
queue.append(node.left)
if node.right:
queue.append(node.right)
# Replace the node with the last node of the tree
last_node = node
queue = [root]
while queue:
node = queue.pop(0)
if node is last_node:
break
if node.left:
if node.left is not last_node:
queue.append(node.left)
else:
node.left = None
if node.right:
if node.right is not last_node:
queue.append(node.right)
else:
node.right = None
if key_node:
key_node.val = last_node.val
return root
```
This code first finds the node to be deleted using BFS traversal. Then, it replaces the node with the last node of the tree by doing another BFS traversal. After that, it updates the value of the deleted node with the value of the last node. Finally, it removes the last node and returns the modified tree.
Note that this implementation does not maintain the balance of the binary tree, and the worst-case time complexity could be O(n) where n is the number of nodes in the tree.

