With Ada.Command_Line; use Ada.Command_Line;
with Ada.Text_IO; use Ada.Text_IO;
with Ada.Strings; use Ada.Strings;
procedure Csv_Arithmetic_Mean is
type Column_Type is access all Float;
type Column_Array is array (Positive range <>) of Column_Type;
procedure Invalid_Parameters is
begin
Put_Line("Invalid command line parameters");
Put_Line("Usage: program_name <csv_file_name> <column_index>");
raise Program_Error;
end Invalid_Parameters;
procedure File_Open_Error is
begin
Put_Line("Could not open the specified file");
raise Program_Error;
end File_Open_Error;
procedure Column_Index_Error is
begin
Put_Line("Invalid column index. Please provide a positive integer.");
raise Program_Error;
end Column_Index_Error;
Filename : constant String := Argument(1);
Column_Index : constant Positive := Positive'Value(Argument(2));
Csv_File : File_Type;
Csv_Line : String(1..512);
Csv_Values : Column_Array(1..512) := (others => null);
Csv_Value : Float := 0.0;
Csv_Count : Natural := 0;
Sum : Float := 0.0;
Mean : Float := 0.0;
Pos : Natural := 1;
begin
if Argument_Count /= 2 then
Invalid_Parameters;
end if;
if not Ada.Text_IO.Exists (Filename) then
File_Open_Error;
end if;
if Column_Index <= 0 then
Column_Index_Error;
end if;
Open(Csv_File, In_File, Filename);
while not End_Of_File(Csv_File) loop
Get_Line(Csv_File, Csv_Line);
if not Ada.Strings.Fixed.Index(Csv_Line, ',', From => 1, Result => Pos) then
continue; -- skip lines without a delimiter
end if;
begin
Csv_Value := Float'Value(Csv_Line(1..Pos-1));
Csv_Count := Csv_Count + 1;
if Csv_Values(Csv_Count) = null then
Csv_Values(Csv_Count) := new Float'(Csv_Value);
else
Csv_Values(Csv_Count).all := Csv_Value;
end if;
exception
when others => null; -- ignore invalid values
end;
end loop;
for I in 1..Csv_Count loop
if Csv_Values(I) /= null and then Csv_Values(I).all /= 0.0 then
Sum := Sum + Csv_Values(I).all;
end if;
end loop;
if Csv_Count > 0 and then Sum /= 0.0 then
Mean := Sum / Csv_Count;
Put_Line("The arithmetic mean of column " & Column_Index'Image & " is: " & Mean'Image);
else
Put_Line("No valid values found in column " & Column_Index'Image);
end if;
Close(Csv_File);
exception
when Program_Error => null;
when others =>
Put_Line("An error occurred: " & Exception_Message(others));
end Csv_Arithmetic_Mean;

