// Generate a cache filename based on the API URL
$cache_filename = md5($api_url) . '.cache';
// Check if the cache file exists and is still valid
if (file_exists($cache_filename) && (time() - filemtime($cache_filename)) < $cache_duration) {
// Load the data from the cache file
$data = file_get_contents($cache_filename);
} else {
// Fetch the data from the API
$ch = curl_init();
curl_setopt($ch, CURLOPT_URL, $api_url);
curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);
curl_setopt($ch, CURLOPT_TIMEOUT, 10);
$data = curl_exec($ch);
$http_status = curl_getinfo($ch, CURLINFO_HTTP_CODE);
curl_close($ch);
// Check for errors and cache the data
if ($http_status == 200 && !empty($data)) {
file_put_contents($cache_filename, $data);
} else {
// Handle errors, such as invalid API response or timeout issues
error_log("Error fetching data from API: HTTP status $http_status");
if (file_exists($cache_filename)) {
// Load the data from the cache file if possible
$data = file_get_contents($cache_filename);
} else {
// Return an error message if the cache is invalid and the API call failed
exit("Error fetching data from API: $http_status");
}
}
}
// Process the data as needed
// ...
?>
```
